SELECT *, CUME_DIST() OVER w_ordered AS quantity_cume_dist, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY unit_price DESC, id) AS seq_no, PERCENT_RANK() OVER w_running AS unit_price_percent_rank, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY order_id, product_id), 4) AS unit_price_share, NTILE(5) OVER w_running_2 AS unit_price_bucket FROM order_items WINDOW w_ordered AS (PARTITION BY order_id ORDER BY quantity DESC), w_running AS (PARTITION BY order_id, product_id ORDER BY unit_price DESC NULLS LAST), w_running_2 AS (ORDER BY unit_price DESC, id);
